1	package relayproof
2	
3	import (
4		"bytes"
5		"io"
6		"strings"
7		"testing"
8	)
9	
10	// Regression coverage for chunked input delivery: the bytes a source hands
11	// over per Read are not aligned to log lines, so the same complete input may
12	// arrive as single bytes, as alternating short and long pieces, or as one
13	// piece spanning several records. Chunking must never change the normalized
14	// events, their order, the physical line numbers, or the failure count, and
15	// a partial chunk must never be mistaken for a whole log line. All inputs
16	// are built in-process, so every case reproduces deterministically offline.
17	
18	// chunkReader replays data in pieces whose sizes cycle through the given
19	// pattern, mirroring a source that delivers arbitrary byte counts per Read.
20	// It never returns (0, nil): once data is exhausted every Read is io.EOF.
21	type chunkReader struct {
22		data  []byte
23		sizes []int
24		pos   int
25		step  int
26	}
27	
28	func (c *chunkReader) Read(p []byte) (int, error) {
29		if c.pos >= len(c.data) {
30			return 0, io.EOF
31		}
32		n := c.sizes[c.step%len(c.sizes)]
33		c.step++
34		if n <= 0 {
35			// A zero-length piece delivers nothing; skip it rather than
36			// returning (0, nil), which a Reader must not do while data remains.
37			return c.Read(p)
38		}
39		if n > len(p) {
40			n = len(p)
41		}
42		if rem := len(c.data) - c.pos; n > rem {
43			n = rem
44		}
45		copy(p, c.data[c.pos:c.pos+n])
46		c.pos += n
47		return n, nil
48	}
49	
50	// chunkPatterns are the delivery shapes every fixture must survive: byte at
51	// a time (every possible split point, including inside UTF-8 sequences,
52	// escape sequences, and CRLF pairs), irregular alternation of short and long
53	// pieces, and pieces large enough to carry several whole records at once.
54	var chunkPatterns = []struct {
55		name  string
56		sizes []int
57	}{
58		{"single byte at a time", []int{1}},
59		{"alternating short and long pieces", []int{1, 4096, 2, 7, 1024, 3, 64}},
60		{"odd small sizes", []int{2, 3, 5, 7, 11, 13}},
61		{"one piece spans many records", []int{1 << 20}},
62	}
63	
64	// normalizeChunked runs NormalizeReader over input delivered in the given
65	// chunk-size pattern and returns the exact output bytes and failure count.
66	func normalizeChunked(t *testing.T, input string, sizes []int) (string, int) {
67		t.Helper()
68		var out bytes.Buffer
69		failures, err := NormalizeReader(&chunkReader{data: []byte(input), sizes: sizes}, &out)
70		if err != nil {
71			t.Fatalf("chunked delivery must not turn into a stream error, got %v", err)
72		}
73		return out.String(), failures
74	}
75	
76	// assertChunkingInvariant verifies that every delivery pattern produces byte
77	// for byte the same output and the same failure count as reading the whole
78	// input at once, and that no chunk boundary introduced replacement
79	// characters into the emitted records.
80	func assertChunkingInvariant(t *testing.T, input string) (string, int) {
81		t.Helper()
82		var whole bytes.Buffer
83		baseFailures, err := NormalizeReader(strings.NewReader(input), &whole)
84		if err != nil {
85			t.Fatalf("whole-input baseline must not fail, got %v", err)
86		}
87		base := whole.String()
88		for _, pattern := range chunkPatterns {
89			t.Run(pattern.name, func(t *testing.T) {
90				got, failures := normalizeChunked(t, input, pattern.sizes)
91				if got != base {
92					t.Fatalf("chunking changed the output\nwhole:   %q\nchunked: %q", base, got)
93				}
94				if failures != baseFailures {
95					t.Fatalf("chunking changed the failure count: got %d, want %d", failures, baseFailures)
96				}
97			})
98		}
99		if strings.Contains(base, "�") {
100			t.Fatalf("output must not contain replacement characters: %q", base)
101		}
102		return base, baseFailures
103	}
104	
105	// chunkedFixtureInput is one stream exercising every hazard at once: aliases,
106	// Chinese and emoji text (multi-byte UTF-8) in mapped and unmapped fields,
107	// JSON escape sequences inside strings, blank lines, an empty-action error
108	// line, a CRLF-terminated line, and a final complete line with no trailing
109	// newline.
110	func chunkedFixtureInput() string {
111		return `{"time":"2026-01-02T08:04:05+08:00","src_ip":"2001:db8::1","event_type":" 登录 ","user":" 爱丽丝 ","note":"换行\n与\"引号\"和中文","emoji":"🚀🙂"}` + "\n" +
112			"\n" +
113			"   \t \n" +
114			`{"timestamp":"2026-01-02T00:00:00Z","action":""}` + "\n" +
115			`{"timestamp":"2026-01-02T00:00:00.5Z","action":"心跳","detail":"转义\\与中文字符"}` + "\r\n" +
116			`{"timestamp":"2026-12-31T23:59:59-01:00","action":"收尾","msg":"结束🚀"}`
117	}
118	
119	// The fixture's business results must hold under every chunking: aliases map
120	// to canonical fields with UTC timestamps and trimmed actions, unknown text
